module width_8to16(
    input clk, 
    input rst_n, 
    input valid_in, 
    input [7:0] data_in,
    output reg valid_out, 
    output reg [15:0] data_out
);
// Add your code here
reg flag;
reg [7:0] data_lock;
always@(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        data_out <= 16'd0;
    end
    else if(valid_in && flag) begin
        data_out <= {data_lock,data_in};
    end
end
always@(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        flag <= 1'd0;
    end
    else if(valid_in && !flag) begin
        flag <= 1'd1;
    end
    else if(valid_in && flag) begin
        flag <= 1'd0;
    end
end
always@(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        data_lock <= 8'd0;
    end
    else if(valid_in && !flag) begin
        data_lock <= data_in;
    end
end
always@(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        valid_out <= 1'd0;
    end
    else if(valid_in && flag) begin
        valid_out <= 1'd1;
    end
    else begin
        valid_out <= 1'd0;
    end
end
endmodule
